responseHandlers.jsonataConvertorExpression:
(
  $isValidCandidateId := function($candidateId) { 
    $type($candidateId) = "string" and $length($candidateId) > 0 
  };

  ($exists(bullhorn_create_application_one[0].errorMessage) or false = $isValidCandidateId(bullhorn_create_application_one[0].candidateId)) 
    ? (
        ($exists(bullhorn_create_application_two[0].errorMessage) or false = $isValidCandidateId(bullhorn_create_application_two[0].candidateId)) 
          ? (
              ($exists(bullhorn_check_application_already_exists[0].errorMessage) or false = $isValidCandidateId(bullhorn_check_application_already_exists[0].candidateId)) 
                ? { 
                    "data": null, 
                    "errors": [ 
                      { 
                        "errorCode": "500", 
                        "errorType": "Internal error", 
                        "message": "Error while creating application on bullhorn.", 
                        "params": { 
                          "bullhorn_create_application_one_error": $string(bullhorn_create_application_one[0].errorMessage), 
                          "bullhorn_create_application_two_error": $string(bullhorn_create_application_two[0].errorMessage), 
                          "error": $string($) 
                        } 
                      } 
                    ] 
                  } 
                : { 
                    "data": { 
                      "candidateId": bullhorn_check_application_already_exists[0].candidateId, 
                      "applicationId": bullhorn_check_application_already_exists[0].applicationId, 
                      "customFields": { 
                        "jobId": bullhorn_check_application_already_exists[0].jobId 
                      } 
                    } 
                  }
            )
          : { 
              "data": { 
                "candidateId": bullhorn_create_application_two[0].candidateId, 
                "applicationId": bullhorn_create_application_two[0].applicationId, 
                "customFields": { 
                  "jobId": bullhorn_create_application_two[0].jobId 
                } 
              } 
            }
      ) 
    : { 
        "data": { 
          "candidateId": bullhorn_create_application_one[0].candidateId, 
          "applicationId": bullhorn_create_application_one[0].applicationId, 
          "customFields": { 
            "jobId": bullhorn_create_application_one[0].jobId 
          } 
        } 
      }
)
